<script setup>
import {ref,onMounted} from 'vue';import {api} from '../api';import {hasPermission} from '../auth';
const props=defineProps({student:Boolean});const emit=defineEmits(['navigate']);const data=ref({items:[],unread:0,total:0}),page=ref(0),error=ref(''),busy=ref(false);
async function load(){busy.value=true;error.value='';try{data.value=await api((props.student?'/public/rankings/student-messages':'/rankings/admin/messages')+'?page='+page.value);}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function open(m){error.value='';try{if(!m.read_at&&(props.student||hasPermission('rankings.messages.update')))await api((props.student?'/public/rankings/student-messages/':'/rankings/admin/messages/')+m.id+'/read',{method:'POST'});await load();emit('navigate',m.target);}catch(e){error.value=e.message;}}
function turn(delta){page.value+=delta;load();}onMounted(load);
</script>
<template><section :class="['inbox',{student}]"><header><h2>站内消息 <small>{{data.unread}} 条未读</small></h2><button type="button" @click="load" :disabled="busy">刷新消息</button></header><p v-if="error" role="alert">{{error}}</p><p v-if="!busy&&!data.items.length">暂无消息</p><article v-for="m in data.items" :key="m.id" :class="{unread:!m.read_at}"><div><strong>{{m.title}}</strong><span>{{m.read_at?'已读':'未读'}} · {{new Date(m.created_at).toLocaleString()}}</span></div><p>{{m.body}}</p><button type="button" @click="open(m)">查看相关记录</button></article><footer><button :disabled="page===0||busy" @click="turn(-1)">上一页</button><span>第 {{page+1}} 页</span><button :disabled="(page+1)*30>=data.total||busy" @click="turn(1)">下一页</button></footer></section></template>
<style scoped>.inbox{background:#fff;border:1px solid #d8e0e3;border-radius:10px;padding:20px;color:#233d47;min-width:0}.inbox h2{font-size:18px;margin:0}.inbox small{font-size:12px;font-weight:400}.inbox header,.inbox footer{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}.inbox article{border-bottom:1px solid #e2e9eb;padding:16px 0}.inbox article div{display:flex;gap:8px;justify-content:space-between;flex-wrap:wrap}.inbox article span{font-size:12px;color:#71818b}.inbox article p{overflow-wrap:anywhere;line-height:1.7}.inbox .unread strong:before{content:'●';color:#148879;margin-right:8px;font-size:10px}.inbox button{padding:8px 12px;border-radius:6px;border:1px solid #cedcde;background:#f4faf8;color:#16766f;cursor:pointer}.inbox button:disabled{opacity:.5;cursor:default}.inbox footer{margin-top:16px}.inbox.student{background:#12213b;border-color:#304664;color:#e7f0ff}.student button{background:#1a3555;border-color:#456687;color:#b6edff}.student .unread strong:before{color:#6ce4ff}.student article{border-color:#304664}.student article span{color:#adbbd4}</style>
